// Package store owns the SQLite file and every write the service performs.
package store

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"net/url"
	"sort"
	"strings"

	_ "modernc.org/sqlite"
)

// Business errors callers can distinguish with errors.Is.
var (
	// ErrInvalidAsset reports a request whose asset fields or dependency
	// references cannot be honored.
	ErrInvalidAsset = errors.New("invalid asset")
	// ErrLineageCycle reports that an upsert would make the dependency graph cyclic.
	ErrLineageCycle = errors.New("lineage cycle")
	// ErrAssetNotFound reports that no asset is registered for the requested id.
	ErrAssetNotFound = errors.New("asset not found")
)

// Asset is one catalog entry together with both of its dependency lists.
type Asset struct {
	ID         string   `json:"id"`
	Type       string   `json:"type"`
	Owner      string   `json:"owner"`
	Upstream   []string `json:"upstream"`
	Downstream []string `json:"downstream"`
}

// UpstreamAsset is an ancestor asset annotated with its shortest reach distance.
type UpstreamAsset struct {
	ID         string   `json:"id"`
	Type       string   `json:"type"`
	Owner      string   `json:"owner"`
	Upstream   []string `json:"upstream"`
	Downstream []string `json:"downstream"`
	Distance   int      `json:"distance"`
}

// Store wraps the SQLite handle so callers never touch database/sql directly.
type Store struct {
	db *sql.DB
}

// Open prepares the database file and the schema this service needs.
func Open(path string) (*Store, error) {
	dsn := "file:" + url.PathEscape(strings.TrimPrefix(path, "file:")) +
		"?_pragma=busy_timeout(5000)&_pragma=foreign_keys(on)&_txlock=immediate"
	db, err := sql.Open("sqlite", dsn)
	if err != nil {
		return nil, fmt.Errorf("open sqlite: %w", err)
	}
	if _, err := db.Exec("PRAGMA journal_mode=WAL"); err != nil {
		db.Close()
		return nil, fmt.Errorf("enable wal: %w", err)
	}
	if _, err := db.Exec(schema); err != nil {
		db.Close()
		return nil, fmt.Errorf("apply schema: %w", err)
	}
	return &Store{db: db}, nil
}

// Ping reports whether the storage layer is usable.
func (s *Store) Ping() error { return s.db.Ping() }

// Close releases the database handle.
func (s *Store) Close() error { return s.db.Close() }

const schema = `
CREATE TABLE IF NOT EXISTS service_metadata (
	key   TEXT PRIMARY KEY,
	value TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS assets (
	id    TEXT PRIMARY KEY,
	type  TEXT NOT NULL,
	owner TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS edges (
	downstream_id TEXT NOT NULL REFERENCES assets(id) ON DELETE CASCADE,
	upstream_id   TEXT NOT NULL REFERENCES assets(id) ON DELETE CASCADE,
	upstream_pos  INTEGER NOT NULL DEFAULT 0,
	downstream_pos INTEGER NOT NULL DEFAULT 0,
	PRIMARY KEY (downstream_id, upstream_id)
);

CREATE INDEX IF NOT EXISTS idx_edges_upstream ON edges(upstream_id);
`

// UpsertAsset registers a new asset or fully replaces the fields and both
// dependency lists of an existing one. The whole change happens in a single
// transaction; a rejected request leaves every prior row untouched.
func (s *Store) UpsertAsset(ctx context.Context, asset Asset) (Asset, bool, error) {
	if asset.ID == "" || asset.Type == "" || asset.Owner == "" {
		return Asset{}, false, ErrInvalidAsset
	}
	upstream := dedupeNonEmpty(asset.Upstream)
	downstream := dedupeNonEmpty(asset.Downstream)
	if len(upstream) != len(asset.Upstream) || len(downstream) != len(asset.Downstream) {
		return Asset{}, false, ErrInvalidAsset
	}

	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return Asset{}, false, fmt.Errorf("begin upsert: %w", err)
	}
	defer tx.Rollback()

	var exists bool
	if err := tx.QueryRowContext(ctx,
		`SELECT EXISTS(SELECT 1 FROM assets WHERE id = ?)`, asset.ID).Scan(&exists); err != nil {
		return Asset{}, false, fmt.Errorf("check asset: %w", err)
	}

	known := make(map[string]bool)
	known[asset.ID] = true
	rows, err := tx.QueryContext(ctx, `SELECT id FROM assets`)
	if err != nil {
		return Asset{}, false, fmt.Errorf("list asset ids: %w", err)
	}
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			rows.Close()
			return Asset{}, false, fmt.Errorf("scan asset id: %w", err)
		}
		known[id] = true
	}
	rows.Close()
	if err := rows.Err(); err != nil {
		return Asset{}, false, fmt.Errorf("iterate asset ids: %w", err)
	}
	for _, id := range upstream {
		if !known[id] {
			return Asset{}, false, ErrInvalidAsset
		}
	}
	for _, id := range downstream {
		if !known[id] {
			return Asset{}, false, ErrInvalidAsset
		}
	}

	cycle, err := wouldCycle(ctx, tx, asset.ID, upstream)
	if err != nil {
		return Asset{}, false, err
	}
	if cycle {
		return Asset{}, false, ErrLineageCycle
	}

	// Preserve positions of the peer side of edges we are about to rewrite.
	peerUpstreamPos := make(map[string]int)
	peerDownstreamPos := make(map[string]int)
	rows, err = tx.QueryContext(ctx,
		`SELECT upstream_id, upstream_pos FROM edges WHERE downstream_id = ?`, asset.ID)
	if err != nil {
		return Asset{}, false, fmt.Errorf("load upstream positions: %w", err)
	}
	for rows.Next() {
		var id string
		var pos int
		if err := rows.Scan(&id, &pos); err != nil {
			rows.Close()
			return Asset{}, false, fmt.Errorf("scan upstream position: %w", err)
		}
		peerUpstreamPos[id] = pos
	}
	rows.Close()
	if err := rows.Err(); err != nil {
		return Asset{}, false, fmt.Errorf("iterate upstream positions: %w", err)
	}
	rows, err = tx.QueryContext(ctx,
		`SELECT downstream_id, downstream_pos FROM edges WHERE upstream_id = ?`, asset.ID)
	if err != nil {
		return Asset{}, false, fmt.Errorf("load downstream positions: %w", err)
	}
	for rows.Next() {
		var id string
		var pos int
		if err := rows.Scan(&id, &pos); err != nil {
			rows.Close()
			return Asset{}, false, fmt.Errorf("scan downstream position: %w", err)
		}
		peerDownstreamPos[id] = pos
	}
	rows.Close()
	if err := rows.Err(); err != nil {
		return Asset{}, false, fmt.Errorf("iterate downstream positions: %w", err)
	}

	if _, err := tx.ExecContext(ctx,
		`INSERT INTO assets(id, type, owner) VALUES(?, ?, ?)
		 ON CONFLICT(id) DO UPDATE SET type = excluded.type, owner = excluded.owner`,
		asset.ID, asset.Type, asset.Owner); err != nil {
		return Asset{}, false, fmt.Errorf("upsert asset: %w", err)
	}

	if _, err := tx.ExecContext(ctx, `DELETE FROM edges WHERE downstream_id = ? OR upstream_id = ?`,
		asset.ID, asset.ID); err != nil {
		return Asset{}, false, fmt.Errorf("delete old edges: %w", err)
	}

	for pos, id := range upstream {
		if _, err := tx.ExecContext(ctx,
			`INSERT INTO edges(downstream_id, upstream_id, upstream_pos, downstream_pos)
			 VALUES(?, ?, ?, ?)`,
			asset.ID, id, pos, peerDownstreamPos[id]); err != nil {
			return Asset{}, false, fmt.Errorf("insert upstream edge: %w", err)
		}
	}
	for pos, id := range downstream {
		if _, err := tx.ExecContext(ctx,
			`INSERT INTO edges(downstream_id, upstream_id, upstream_pos, downstream_pos)
			 VALUES(?, ?, ?, ?)`,
			id, asset.ID, peerUpstreamPos[id], pos); err != nil {
			return Asset{}, false, fmt.Errorf("insert downstream edge: %w", err)
		}
	}

	if err := tx.Commit(); err != nil {
		return Asset{}, false, fmt.Errorf("commit upsert: %w", err)
	}

	saved, err := s.getAsset(ctx, asset.ID)
	if err != nil {
		return Asset{}, exists, err
	}
	return saved, exists, nil
}

// wouldCycle reports whether the asset's prospective upstream list lets the
// asset reach itself by following upstream edges (direct self-reference
// included). Existing edges touching the asset are treated as replaced.
func wouldCycle(ctx context.Context, tx *sql.Tx, id string, upstream []string) (bool, error) {
	adjacency := make(map[string][]string)
	for _, u := range upstream {
		adjacency[id] = append(adjacency[id], u)
	}
	rows, err := tx.QueryContext(ctx,
		`SELECT downstream_id, upstream_id FROM edges WHERE downstream_id <> ?`, id)
	if err != nil {
		return false, fmt.Errorf("load edges for cycle check: %w", err)
	}
	for rows.Next() {
		var downstream, upstreamID string
		if err := rows.Scan(&downstream, &upstreamID); err != nil {
			rows.Close()
			return false, fmt.Errorf("scan edge: %w", err)
		}
		adjacency[downstream] = append(adjacency[downstream], upstreamID)
	}
	rows.Close()
	if err := rows.Err(); err != nil {
		return false, fmt.Errorf("iterate edges: %w", err)
	}

	frontier := append([]string(nil), upstream...)
	seen := map[string]bool{}
	for len(frontier) > 0 {
		current := frontier[0]
		frontier = frontier[1:]
		if current == id {
			return true, nil
		}
		if seen[current] {
			continue
		}
		seen[current] = true
		frontier = append(frontier, adjacency[current]...)
	}
	return false, nil
}

// ListAssets returns every registered asset ordered by id, optionally limited
// to assets whose type equals assetType.
func (s *Store) ListAssets(ctx context.Context, assetType string) ([]Asset, error) {
	query := `SELECT id, type, owner FROM assets`
	var args []any
	if assetType != "" {
		query += ` WHERE type = ?`
		args = append(args, assetType)
	}
	query += ` ORDER BY id ASC`

	rows, err := s.db.QueryContext(ctx, query, args...)
	if err != nil {
		return nil, fmt.Errorf("list assets: %w", err)
	}
	defer rows.Close()

	assets := []Asset{}
	index := map[string]int{}
	for rows.Next() {
		var asset Asset
		asset.Upstream = []string{}
		asset.Downstream = []string{}
		if err := rows.Scan(&asset.ID, &asset.Type, &asset.Owner); err != nil {
			return nil, fmt.Errorf("scan asset: %w", err)
		}
		index[asset.ID] = len(assets)
		assets = append(assets, asset)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("iterate assets: %w", err)
	}
	if len(assets) == 0 {
		return assets, nil
	}
	if err := s.hydrateEdges(ctx, assets, index); err != nil {
		return nil, err
	}
	return assets, nil
}

func (s *Store) hydrateEdges(ctx context.Context, assets []Asset, index map[string]int) error {
	ids := make([]any, 0, len(assets))
	placeholders := make([]string, 0, len(assets))
	for id := range index {
		ids = append(ids, id)
		placeholders = append(placeholders, "?")
	}
	joined := strings.Join(placeholders, ",")

	rows, err := s.db.QueryContext(ctx,
		`SELECT downstream_id, upstream_id, upstream_pos FROM edges
		 WHERE downstream_id IN (`+joined+`) ORDER BY upstream_pos ASC, upstream_id ASC`, ids...)
	if err != nil {
		return fmt.Errorf("load upstream lists: %w", err)
	}
	for rows.Next() {
		var downstream, upstreamID string
		var pos int
		if err := rows.Scan(&downstream, &upstreamID, &pos); err != nil {
			rows.Close()
			return fmt.Errorf("scan upstream edge: %w", err)
		}
		if idx, ok := index[downstream]; ok {
			assets[idx].Upstream = append(assets[idx].Upstream, upstreamID)
		}
	}
	rows.Close()
	if err := rows.Err(); err != nil {
		return fmt.Errorf("iterate upstream edges: %w", err)
	}

	rows, err = s.db.QueryContext(ctx,
		`SELECT upstream_id, downstream_id, downstream_pos FROM edges
		 WHERE upstream_id IN (`+joined+`) ORDER BY downstream_pos ASC, downstream_id ASC`, ids...)
	if err != nil {
		return fmt.Errorf("load downstream lists: %w", err)
	}
