// UpsertAsset validates and registers an asset. Upstream and downstream lists are
// deduplicated and fully replace the previous lists inside a single transaction;
// no edge from the previous registration survives unless the new list names it.
func (s *Store) UpsertAsset(ctx context.Context, asset Asset) (bool, Asset, error) {
	upstream, upDup := dedupe(asset.Upstream)
	downstream, downDup := dedupe(asset.Downstream)
	if asset.ID == "" || asset.Type == "" || asset.Owner == "" || upDup || downDup {
		return false, Asset{}, ErrInvalidAsset
	}

	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return false, Asset{}, err
	}
	defer tx.Rollback()

	var existed int
	if err := tx.QueryRowContext(ctx, `SELECT 1 FROM assets WHERE id = ?`, asset.ID).Scan(&existed); err != nil && !errors.Is(err, sql.ErrNoRows) {
		return false, Asset{}, err
