	downPos := loadPositions(ctx, tx, `SELECT upstream_id, downstream_pos FROM edges WHERE downstream_id = ?`, asset.ID)

	if _, err := tx.ExecContext(ctx, `DELETE FROM edges WHERE upstream_id = ? OR downstream_id = ?`, asset.ID, asset.ID); err != nil {
		return false, Asset{}, err
