		for rows.Next() {
			var up string
			if err := rows.Scan(&up); err != nil {
				rows.Close()
				return nil, err
			}
			if _, seen := visited[up]; !seen {
				visited[up] = distance
				next = append(next, up)
			}
		}
		rows.Close()
		if err := rows.Err(); err != nil {
			return nil, err
		}
		current = frontier{ids: next, distance: distance}
	}

	if len(visited) == 1 {
		return []UpstreamAsset{}, nil
	}
	ids := make([]string, 0, len(visited)-1)
	for neighbor := range visited {
		if neighbor != id {
