func validateReferences(ctx context.Context, tx *sql.Tx, id string, upstream, downstream []string) error {
	neighbors := make(map[string]struct{}, len(upstream)+len(downstream))
	for _, neighbor := range upstream {
		if neighbor == "" {
			return ErrInvalidAsset
		}
		neighbors[neighbor] = struct{}{}
	}
	for _, neighbor := range downstream {
		if neighbor == "" {
			return ErrInvalidAsset
		}
		neighbors[neighbor] = struct{}{}
	}
	for neighbor := range neighbors {
		if neighbor == id {
