func validateCycle(ctx context.Context, tx *sql.Tx, id string, upstream, downstream []string) error {
	adjacency := map[string][]string{}
	rows, err := tx.QueryContext(ctx, `SELECT downstream_id, upstream_id FROM edges`)
	if err != nil {
		return err
	}
	for rows.Next() {
		var downID, upID string
		if err := rows.Scan(&downID, &upID); err != nil {
			rows.Close()
			return err
		}
		adjacency[downID] = append(adjacency[downID], upID)
	}
	rows.Close()
	if err := rows.Err(); err != nil {
		return err
	}

	adjacency[id] = upstream
	starts := make(map[string]struct{}, len(upstream)+len(downstream))
	for _, neighbor := range upstream {
		starts[neighbor] = struct{}{}
	}
	for _, neighbor := range downstream {
		starts[neighbor] = struct{}{}
	}

	for start := range starts {
		seen := map[string]bool{}
		pending := []string{start}
		for len(pending) > 0 {
			node := pending[0]
			pending = pending[1:]
			if node == id {
				return ErrLineageCycle
			}
			if seen[node] {
				continue
			}
			seen[node] = true
			pending = append(pending, adjacency[node]...)
		}
	}
	return nil
